float hash(float2 p) { return frac(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }
float layer(float2 p, float cell, float keep, float seed) {
  float2 id = floor(p / cell);
  float h = hash(id + seed);
  if (h < keep) return 0.0;
  float2 at = (id + float2(hash(id + seed + 1.7), hash(id + seed + 4.1)) * 0.8 + 0.1) * cell;
  float r = 0.55 + 1.25 * hash(id + seed + 9.3);
  float d = length(p - at);
  float tw = 0.75 + 0.25 * sin(time() * (1.5 + 3.0 * hash(id + seed + 2.2)) + h * 40.0);
  return saturate(r + 0.6 - d) * (0.35 + 0.65 * hash(id + seed + 5.5)) * tw;
}
float4 shade(float2 pos, float px) {
  float2 drift = float2(0.0, param(0));
  float b = layer(pos - drift * 0.35, 46.0, 0.80, 0.0) + layer(pos - drift * 0.7, 83.0, 0.84, 17.0)
          + 1.3 * layer(pos - drift, 151.0, 0.9, 41.0);
  float3 c = lerp(float3(0.70, 0.80, 1.0), float3(1.0, 0.95, 0.86), hash(floor(pos / 46.0)));
  return float4(float3(0.0012, 0.0014, 0.0024) + c * b, 1.0);
}

